(2, 'An hPer2 phosphorylation site mutation in familial advanced sleep phase syndrome', 'Toh KL, Jones CR, He Y, Eide EJ, Hinz WA, Virshup DM, Ptácek LJ, Fu YH', 'Science', 2001, '11232563', '10.1126/science.1057499', 'PubMed'),
(3, 'A length polymorphism in the circadian clock gene Per3 is linked to delayed sleep phase syndrome and extreme diurnal preference', 'Archer SN, Robilliard DL, Skene DJ, Smits M, Williams A, Arendt J, von Schantz M', 'Sleep', 2003, '12841365', '10.1093/sleep/26.4.413', 'PubMed'),
(4, 'A CLOCK polymorphism associated with human diurnal preference', 'Katzenberg D, Young T, Finn L, Lin L, King DP, Takahashi JS, Mignot E', 'Sleep', 1998, '9779516', '10.1093/sleep/21.6.569', 'PubMed'),
(5, 'Mutation of the Human Circadian Clock Gene CRY1 in Familial Delayed Sleep Phase Disorder', 'Patke A, Murphy PJ, Onat OE, Carrion-Castillo A, Stevers J, Meyer D, Bilguvar K, Czeisler CA, Young MW, et al.', 'Cell', 2017, '28388406', '10.1016/j.cell.2017.03.027', 'PubMed'),
(6, 'Complex HLA-DR and -DQ interactions confer risk of narcolepsy-cataplexy in three ethnic groups', 'Mignot E, Lin L, Rogers W, Honda Y, Qiu X, Lin X, Okun M, Hohjoh H, Miki T, Risch N', 'American Journal of Human Genetics', 2001, '11179016', '10.1086/318799', 'PubMed'),
(7, 'Hypocretin (orexin) deficiency in human narcolepsy', 'Nishino S, Ripley B, Overeem S, Lammers GJ, Mignot E', 'The Lancet', 2000, '10615891', '10.1016/S0140-6736(99)05582-8', 'PubMed'),
(8, 'A mutation in a case of early onset narcolepsy and a generalized absence of hypocretin peptides in human narcoleptic brains', 'Peyron C, Faraco J, Rogers W, Ripley B, Overeem S, Charnay Y, Nevsimalova S, Aldrich M, Nishino S, Mignot E', 'Nature Medicine', 2000, '10988907', '10.1038/79690', 'PubMed'),
(9, 'Association between a serotonin transporter length polymorphism and primary insomnia', 'Deuschle M, Schredl M, Schilling C, Wüst S, Frank J, Witt SH, Rietschel M', 'Sleep', 2010, '20337192', '10.1093/sleep/33.3.343', 'PubMed'),
(10, 'A functional genetic variation of adenosine deaminase affects the duration and intensity of deep sleep in humans', 'Rétey JV, Adam M, Khatami R, Luhmann UF, Jung HH, Berger W, Landolt HP', 'PNAS USA', 2005, '16223877', '10.1073/pnas.0505436102', 'PubMed'),
(11, 'Brain-Derived Neurotrophic Factor (BDNF) Val66Met polymorphism is associated with cognitive impairment in insomnia patients', 'Gong L, Xu R, Liu D, Ji M, Cen C, Yuan X, Chen G, Li D, Ning Y', 'Psychiatry Research', 2018, '30076879', '10.1016/j.psychres.2018.07.039', 'PubMed'),
(12, 'The hyperarousal model of insomnia: a review of the concept and its evidence', 'Riemann D, Spiegelhalder K, Feige B, Voderholzer U, Berger M, Perlis M, Nissen C', 'Sleep Medicine Reviews', 2010, '19481481', '10.1016/j.smrv.2009.04.002', 'PubMed'),
(13, 'Association between tumor necrosis factor-alpha-308G/A polymorphism and obstructive sleep apnea: a meta-analysis', 'Huang J, Liao N, Huang QP, Xie ZF', 'Genetic Testing and Molecular Biomarkers', 2012, '22176251', '10.1089/gtmb.2011.0150', 'PubMed'),
(14, 'Roles of interleukin (IL)-6 gene polymorphisms, serum IL-6 levels, and treatment in obstructive sleep apnea: a meta-analysis', 'Hu Y, Shen F, Long Y, Cao H', 'Sleep and Breathing', 2016, '26589715', '10.1007/s11325-015-1284-8', 'PubMed'),
(15, 'Serum inflammatory markers in obstructive sleep apnea: a meta-analysis', 'Nadeem R, Molnar J, Madbouly EM, Nida M, Aggarwal S, Sajid H, Naseem J, Loomis R', 'Journal of Clinical Sleep Medicine', 2013, '23541571', '10.5664/jcsm.3070', 'PubMed'),
(16, 'Elevation of plasma cytokines in disorders of excessive daytime sleepiness: role of sleep disturbance and obesity', 'Vgontzas AN, Papanicolaou DA, Bixler EO, Kales A, Tyson K, Chrousos GP', 'Journal of Clinical Endocrinology & Metabolism', 1997, '9141509', '10.1210/jcem.82.5.9141509', 'PubMed'),
(17, 'Genome-wide association study of restless legs syndrome identifies common variants in three genomic regions', 'Winkelmann J, Schormair B, Lichtner P, Ripke S, Xiong L, Jalilzadeh S, Fulda S, Meitinger T, et al.', 'Nature Genetics', 2007, '17637780', '10.1038/ng2099', 'PubMed'),
(18, 'Iron status and restless legs syndrome in the elderly', 'O''Keeffe ST, Gavin K, Lavan JN', 'Age and Ageing', 1994, '8042674', '10.1093/ageing/23.3.200', 'PubMed'),
(19, 'The transcriptional repressor DEC2 regulates sleep length in mammals', 'He Y, Jones CR, Fujiki N, Xu Y, Guo B, Holder JL Jr, Rossner MJ, Nishino S, Fu YH', 'Science', 2009, '19679812', '10.1126/science.1174443', 'PubMed'),
(20, 'GBA variants in REM sleep behavior disorder: a multicenter study', 'Krohn L, Öztürk ZN, Borsche M, Gan-Or Z, et al.', 'Neurology', 2020, '32591690', '10.1212/WNL.0000000000010011', 'PubMed'),
(21, 'Fine-mapping of SNCA in rapid eye movement sleep behavior disorder and overt synucleinopathies', 'Krohn L, Heilbron K, Blauwendraat C, Reynolds RH, et al., Gan-Or Z', 'Annals of Neurology', 2020, '31976583', '10.1002/ana.25687', 'PubMed'),
(22, 'Case report: A novel missense variant in melanopsin associates with delayed sleep phenotype: Whole genome sequencing study', 'Markussen M, Vedel-Krogh S, Jensen BV, Jennum PJ, et al.', 'Frontiers in Genetics', 2022, '36246649', '10.3389/fgene.2022.968984', 'PubMed'),
(23, 'Light suppresses melatonin secretion in humans', 'Lewy AJ, Wehr TA, Goodwin FK, Newsome DA, Markey SP', 'Science', 1980, '7434030', '10.1126/science.7434030', 'PubMed'),
(24, 'Phototransduction by retinal ganglion cells that set the circadian clock', 'Berson DM, Dunn FA, Takao M', 'Science', 2002, '11834834', '10.1126/science.1067262', 'PubMed');
INSERT INTO disorders (id, name, description, category, synonyms, icd11_code) VALUES
(1, 'Circadian Rhythm Sleep-Wake Disorder', 'Persistent or recurrent pattern of sleep disruption resulting from alteration of the endogenous circadian timing system or misalignment between the endogenous circadian clock and external 24-hr environmental demands.', 'Circadian Rhythm Sleep-Wake Disorder', 'CRSWD, Advanced Sleep Phase Syndrome (ASPS), Delayed Sleep-Wake Phase Disorder (DSWPD)', '7A60'),
(2, 'Narcolepsy Type 1', 'Central disorder of hypersomnolence characterized by excessive daytime sleepiness, cataplexy (sudden loss of muscle tone triggered by emotion), and selective autoimmune destruction of orexin/hypocretin neurons.', 'Sleep-Wake Disorder', 'Narcolepsy with Cataplexy, Hypocretin Deficiency Syndrome', '7A20.0'),
(3, 'Chronic Insomnia Disorder', 'Persistent difficulty with sleep initiation, consolidation, or quality occurring despite adequate opportunity for sleep, driven by sustained neuroendocrine and psychophysiological hyperarousal.', 'Sleep-Wake Disorder', 'Primary Insomnia, Psychophysiological Insomnia', '7A00'),
(4, 'Obstructive Sleep Apnea', 'Sleep-related breathing disorder characterized by repetitive episodes of partial or complete upper airway collapse, resulting in intermittent hypoxemia, sympathetic activation, and systemic inflammation.', 'Sleep-Related Breathing Disorder', 'OSA, Obstructive Sleep Apnea-Hypopnea Syndrome', '7A40.0'),
(5, 'Restless Legs Syndrome', 'Sensorimotor neurological movement disorder marked by an irresistible urge to move the limbs (usually legs), typically accompanied by uncomfortable sensations that worsen during evening rest or inactivity.', 'Movement Disorder', 'RLS, Willis-Ekbom Disease (WED)', '7A80'),
(6, 'Short Sleep Duration Phenotype (Natural Short Sleeper)', 'Inherited physiological sleep duration trait in which individuals maintain normal cognitive and metabolic function on habitually less than 6 hours of sleep per 24-hour cycle.', 'Sleep-Wake Disorder', 'Familial Natural Short Sleep (FNSS)', '7A2Z'),
(7, 'REM Sleep Behavior Disorder', 'Parasomnia characterized by the loss of normal motor atonia during rapid eye movement (REM) sleep, leading to violent dream-enactment motor behaviors and potential dream-related injury.', 'Parasomnia', 'iRBD, Isolated REM Sleep Behavior Disorder', '7A71');
INSERT INTO genes (id, symbol, name, ncbi_id, uniprot_id, chromosome, description) VALUES
(1, 'PER2', 'Period Circadian Regulator 2', 8864, 'O15055', '2q37.3', 'Core component of the circadian transcription-translation feedback loop. Missense mutation (Ser662Gly) accelerates phosphorylation by casein kinase 1, shortening circadian period and causing FASPS.'),
(2, 'PER3', 'Period Circadian Regulator 3', 8863, 'P56645', '1p36.23', 'Circadian clock-associated gene containing a functional 54-bp VNTR polymorphism modulating extreme diurnal preference, delayed sleep phase vulnerability, and homeostatic slow-wave response to sleep loss.'),
(3, 'CLOCK', 'Clock Circadian Regulator', 9575, 'O15516', '4q12', 'Basic helix-loop-helix-PAS transcription factor that heterodimerizes with BMAL1 to activate circadian transcription. The 3111T/C 3-prime UTR polymorphism is associated with evening diurnal preference and delayed sleep timing.'),
(4, 'CRY1', 'Cryptochrome Circadian Regulator 1', 1407, 'Q16526', '12q24.11', 'Transcriptional repressor of CLOCK:BMAL1. A dominant gain-of-function splice-site mutation resulting in exon 11 skipping slows the circadian oscillator, causing familial Delayed Sleep Phase Disorder.'),
(5, 'HLA-DQB1', 'Major Histocompatibility Complex, Class II, DQ Beta 1', 3119, 'P01920', '6p21.32', 'HLA class II beta chain mediating antigen presentation to CD4+ T cells. The HLA-DQB1*06:02 allele is present in >98% of Narcolepsy Type 1 patients, conferring essential autoimmune susceptibility.'),
(6, 'HCRT', 'Hypocretin Neuropeptide Precursor', 3060, 'O43612', '17q21.2', 'Encodes the prepro-protein cleaved into orexin-A (hypocretin-1) and orexin-B (hypocretin-2). Mutations or selective autoimmune destruction of HCRT-producing neurons cause human Narcolepsy Type 1.'),
(7, 'SLC6A4', 'Solute Carrier Family 6 Member 4 (5-HTT)', 6532, 'P31645', '17q11.2', 'Presynaptic serotonin transporter regulating synaptic clearance. The 5-HTTLPR short (s) allele reduces transporter expression and is significantly more frequent in patients with primary chronic insomnia.'),
(8, 'ADA', 'Adenosine Deaminase', 100, 'P00568', '20q13.12', 'Catalyzes irreversible deamination of adenosine to inosine. A functional G22A (Asp8Gly) polymorphism alters homeostatic sleep pressure, slow-wave sleep duration, and deep sleep intensity.'),
(9, 'BDNF', 'Brain Derived Neurotrophic Factor', 627, 'P23560', '11p14.1', 'Neurotrophin critical for activity-dependent synaptic plasticity. The functional Val66Met (rs6265) polymorphism impairs mature secretion and is associated with insomnia susceptibility and cognitive deficits.'),
(10, 'TNF', 'Tumor Necrosis Factor', 7124, 'P01375', '6p21.33', 'Key pro-inflammatory cytokine and somnogenic signaling molecule. The promoter -308G/A polymorphism (rs1800629) is significantly associated with increased risk of Obstructive Sleep Apnea in meta-analyses.'),
(11, 'IL6', 'Interleukin 6', 3569, 'P05231', '7p15.3', 'Pro-inflammatory cytokine whose systemic circulating levels rise in response to nocturnal hypoxemia. Functional promoter variants (-174G/C, -572C/G) associate with Obstructive Sleep Apnea susceptibility.'),
(12, 'MEIS1', 'Meis Homeobox 1', 4211, 'O00470', '2p14', 'Homeobox transcription factor. Replicated genome-wide association study (GWAS) locus (rs2300478) with the strongest known genetic effect size in Restless Legs Syndrome susceptibility.'),
(13, 'BTBD9', 'BTB Domain Containing 9', 114781, 'Q96Q07', '6p21.2', 'BTB domain-containing protein. Replicated GWAS locus (rs9296265) strongly associated with Restless Legs Syndrome and elevated periodic limb movement index during sleep.'),
(14, 'MAP2K5', 'Mitogen-Activated Protein Kinase Kinase 5', 5607, 'Q13163', '15q23', 'Dual specificity protein kinase in the MEK5/ERK5 signaling cascade. Replicated intergenic GWAS variant (rs12593813) associated with Restless Legs Syndrome susceptibility.'),
(15, 'BHLHE41', 'Basic Helix-Loop-Helix Family Member E41 (DEC2)', 79365, 'Q9C0J9', '12p12.1', 'Transcriptional repressor modulating circadian E-box transcription. A point mutation (P385R/P384R) reduces repressor activity and confers a natural short sleep phenotype (~6 hours daily).'),
(16, 'GBA1', 'Glucosylceramidase Beta 1', 2629, 'P04062', '1q22', 'Lysosomal enzyme hydrolyzing glucosylceramide. Pathogenic variants represent the strongest single genetic risk factor for isolated REM Sleep Behavior Disorder (OR = 2.45).'),
(17, 'SNCA', 'Synuclein Alpha', 6622, 'P37840', '4q22.1', 'Encodes alpha-synuclein, whose pathological aggregation in pontomedullary brainstem REM-atonia circuits causes dream enactment. Fine-mapped variant rs10005233 associates with isolated RBD.'),
(18, 'OPN4', 'Opsin 4 (Melanopsin)', 94233, 'Q9UHM6', '10q23.2', 'Photopigment of intrinsically photosensitive retinal ganglion cells driving circadian photoentrainment. Rare loss-of-function missense variant (R168C) impairs signaling and associates with DSWPD.');
INSERT INTO biomarkers (id, name, type, sample_type, description, standard_unit, reference_range) VALUES
(1, 'Melatonin', 'Hormone', 'Saliva / Serum', 'Pineal indoleamine hormone synthesized under suprachiasmatic nucleus control; gold standard physiological marker of endogenous circadian phase and timing.', 'pg/mL', 'Nocturnal Peak: 10 - 60 pg/mL; Daytime: < 5 pg/mL'),
(2, 'Orexin-A (Hypocretin-1)', 'Neuropeptide', 'Cerebrospinal Fluid (CSF)', 'Hypothalamic wake-stabilizing neuropeptide. CSF concentration <= 110 pg/mL is an established diagnostic criterion for Narcolepsy Type 1 in ICSD-3 clinical guidelines.', 'pg/mL', 'Normal: > 200 pg/mL; Diagnostic for Type 1: <= 110 pg/mL'),
(3, 'Cortisol', 'Hormone', 'Serum / Saliva', 'Glucocorticoid hormone produced by adrenal cortex. Elevated evening nadir and 24-hr secretion reflect systemic hypothalamic-pituitary-adrenal (HPA) hyperarousal in chronic insomnia.', 'μg/dL', 'Morning: 6 - 23 μg/dL; Midnight Nadir: < 1.5 μg/dL'),
(4, 'Polysomnography AHI', 'Physiological Index', 'Overnight Sleep Study', 'Apnea-Hypopnea Index; hourly frequency of apneas and hypopneas during overnight polysomnography establishing clinical diagnosis and severity stratification of OSA.', 'events/hr', 'Normal: < 5; Mild: 5-14; Moderate: 15-29; Severe: >= 30'),
(5, 'Interleukin-6 (IL-6)', 'Cytokine', 'Serum / Plasma', 'Pro-inflammatory cytokine significantly elevated in Obstructive Sleep Apnea, correlating with intermittent nocturnal hypoxemia duration and severity.', 'pg/mL', 'Healthy Baseline: < 5.0 pg/mL; Elevated in OSA: 5 - 25+ pg/mL'),
(6, 'Tumor Necrosis Factor-alpha (TNF-α)', 'Cytokine', 'Serum / Plasma', 'Master inflammatory mediator and somnogenic signaling protein whose circulating levels correlate with daytime somnolence and hypoxemic desaturation in OSA.', 'pg/mL', 'Healthy Baseline: < 8.1 pg/mL; Elevated in OSA: 8.5 - 20+ pg/mL'),
(7, 'Adenosine', 'Purine Nucleoside', 'Plasma / Microdialysate', 'Endogenous homeostatic somnogen accumulating in basal forebrain during extended wakefulness, mediating homeostatic sleep drive (Process S).', 'nmol/L', 'Basal Resting: 10 - 250 nmol/L'),
(8, 'Ferritin', 'Protein', 'Serum', 'Intracellular iron storage protein. Serum ferritin < 50-75 ng/mL reflects central and peripheral iron insufficiency, inversely predicting Restless Legs Syndrome severity.', 'ng/mL', 'Clinical Target in RLS: > 75 ng/mL; Low / Symptom-Triggering: < 50 ng/mL'),
(9, 'Dim Light Melatonin Onset (DLMO)', 'Physiological Index', 'Saliva in dim light', 'Objective circadian phase milestone determined as the clock time when salivary melatonin crosses a reliable biological threshold (~4 pg/mL) under dim light conditions.', 'Clock Time', 'Habitual DLMO: ~20:30 - 22:00 in entrained adults');
INSERT INTO gene_disorder (gene_id, disorder_id, evidence, evidence_type, source_database, pmid, doi) VALUES
(1, 1, 'Missense mutation (Ser662Gly) in human PER2 accelerates phosphorylation by CK1 epsilon, shortening the circadian period and causing FASPS.', 'Functional / Family Study', 'PubMed', '11232563', '10.1126/science.1057499'),
(2, 1, 'Variable number tandem repeat (VNTR) 54-bp length polymorphism in PER3 associates with delayed sleep phase syndrome and extreme diurnal preference.', 'Genetic Association Study', 'PubMed', '12841365', '10.1093/sleep/26.4.413'),
(3, 1, '3111T/C single nucleotide polymorphism in the 3-prime UTR of CLOCK associates with evening diurnal preference and delayed sleep timing.', 'Genetic Association Study', 'PubMed', '9779516', '10.1093/sleep/21.6.569'),
(4, 1, 'Dominant gain-of-function CRY1 splice-site mutation causing exon 11 skipping slows the circadian oscillator, causing familial Delayed Sleep Phase Disorder.', 'Functional / Family Study', 'PubMed', '28388406', '10.1016/j.cell.2017.03.027'),
(5, 2, 'HLA-DQB1*06:02 confers essential autoimmune susceptibility for Narcolepsy Type 1, present in >98% of cataplectic patients.', 'Genetic Association Study', 'PubMed', '11179016', '10.1086/318799'),
(6, 2, 'Point mutation in prepro-hypocretin (HCRT) impairs peptide processing and produces generalized loss of hypocretin peptides, manifesting as Narcolepsy Type 1.', 'Functional / Family Study', 'PubMed', '10988907', '10.1038/79690'),
(7, 3, 'Short (s) allele of the 5-HTTLPR serotonin transporter polymorphism is significantly elevated in patients with primary chronic insomnia.', 'Genetic Association Study', 'PubMed', '20337192', '10.1093/sleep/33.3.343'),
(8, 3, 'Functional G22A (Asp8Gly) polymorphism of adenosine deaminase affects deep sleep duration and slow-wave sleep intensity, modulating sleep fragmentation.', 'Functional Study', 'PubMed', '16223877', '10.1073/pnas.0505436102'),
(9, 3, 'BDNF Val66Met (rs6265) polymorphism impairs activity-dependent secretion and is significantly associated with insomnia susceptibility and cognitive deficit.', 'Genetic Association Study', 'PubMed', '30076879', '10.1016/j.psychres.2018.07.039'),
(10, 4, 'TNF promoter -308G/A single nucleotide polymorphism (rs1800629) is significantly associated with Obstructive Sleep Apnea risk across pooled meta-analyses.', 'Meta-Analysis', 'PubMed', '22176251', '10.1089/gtmb.2011.0150'),
(11, 4, 'Functional IL6 promoter polymorphisms (-174G/C, -572C/G) significantly correlate with Obstructive Sleep Apnea susceptibility and circulating cytokine levels.', 'Meta-Analysis', 'PubMed', '26589715', '10.1007/s11325-015-1284-8'),
(12, 5, 'MEIS1 intronic variant rs2300478 shows genome-wide significant association with Restless Legs Syndrome, conferring the largest known genetic risk effect.', 'GWAS', 'PubMed', '17637780', '10.1038/ng2099'),
(13, 5, 'BTBD9 locus variant rs9296265 associates with Restless Legs Syndrome and elevated periodic limb movement index at genome-wide significance.', 'GWAS', 'PubMed', '17637780', '10.1038/ng2099'),
(14, 5, 'MAP2K5/SKOR1 intergenic locus variant rs12593813 demonstrates replicated genome-wide significant association with Restless Legs Syndrome.', 'GWAS', 'PubMed', '17637780', '10.1038/ng2099'),
(15, 6, 'Point mutation in BHLHE41 (DEC2 P385R/P384R) reduces transcriptional repression of CLOCK/BMAL1, producing an inherited natural short sleep duration (~6 hrs).', 'Functional / Family Study', 'PubMed', '19679812', '10.1126/science.1174443'),
(16, 7, 'GBA1 pathogenic variants represent the strongest single genetic predisposing factor for isolated REM Sleep Behavior Disorder in multicenter cohorts (OR = 2.45).', 'Genetic Association Study', 'PubMed', '32591690', '10.1212/WNL.0000000000010011'),
(17, 7, 'Fine-mapping of SNCA in isolated REM Sleep Behavior Disorder identifies significant 5-prime risk variant rs10005233, linking to early pontine synucleinopathy.', 'Genetic Association Study', 'PubMed', '31976583', '10.1002/ana.25687'),
(18, 1, 'Rare loss-of-function missense variant (R168C) in melanopsin (OPN4) impairs photic retinal signaling to the SCN, causing Delayed Sleep-Wake Phase Disorder.', 'Functional Study', 'PubMed', '36246649', '10.3389/fgene.2022.968984');
INSERT INTO gene_biomarker (gene_id, biomarker_id, relationship, evidence, evidence_type, source_database, pmid, doi) VALUES
(1, 1, 'Circadian Phase Driver', 'PER2 feedback loops regulate the circadian timing and phase angle of nocturnal pineal melatonin secretion.', 'Functional Study', 'PubMed', '11232563', '10.1126/science.1057499'),
(1, 9, 'DLMO Phase Determinant', 'PER2 mutations cause an advance in dim light melatonin onset by approximately 4 hours relative to standard clock time.', 'Clinical Study', 'PubMed', '10499924', '10.1038/13511'),
(5, 2, 'Autoimmune Target Pathway', 'HLA-DQB1*06:02 antigen presentation triggers autoimmune destruction of orexin-producing neurons, eliminating CSF orexin-A.', 'Clinical Study', 'PubMed', '11179016', '10.1086/318799'),
(6, 2, 'Precursor Gene Product', 'HCRT encodes the prepro-hypocretin polypeptide precursor that is enzymatically processed into mature orexin-A and orexin-B peptides.', 'Functional Study', 'PubMed', '10988907', '10.1038/79690'),
(7, 3, 'HPA Axis Neuroendocrine Modulation', 'Altered 5-HTTLPR serotonin transporter expression elevates central corticotropin-releasing hormone drive and evening cortisol.', 'Clinical Study', 'PubMed', '20337192', '10.1093/sleep/33.3.343'),
(8, 7, 'Enzymatic Substrate Degradation', 'Adenosine deaminase catalyzes irreversible hydrolytic deamination of somnogenic adenosine into inosine in the basal forebrain.', 'Functional Study', 'PubMed', '16223877', '10.1073/pnas.0505436102'),
(10, 6, 'Cytokine Encoding Gene', 'TNF gene directly encodes tumor necrosis factor-alpha; the -308G/A promoter variant upregulates transcription and plasma protein levels.', 'Meta-Analysis', 'PubMed', '22176251', '10.1089/gtmb.2011.0150'),
(11, 5, 'Cytokine Encoding Gene', 'IL6 gene directly encodes interleukin-6; promoter polymorphisms (-174G/C, -572C/G) regulate transcriptional rate and circulating IL-6.', 'Meta-Analysis', 'PubMed', '26589715', '10.1007/s11325-015-1284-8'),
(18, 1, 'Photic Retino-Hypothalamic Circuit', 'Melanopsin (OPN4) ipRGC projections to the suprachiasmatic nucleus mediate light-induced suppression of pineal melatonin.', 'Functional Study', 'PubMed', '11834834', '10.1126/science.1067262');
INSERT INTO disorder_biomarker (disorder_id, biomarker_id, evidence, evidence_type, source_database, pmid, doi) VALUES
(1, 1, 'Abnormal phase angle and shifted peak timing of nocturnal melatonin secretion characterize circadian rhythm sleep disorders.', 'Physiological Study', 'PubMed', '10499924', '10.1038/13511'),
(1, 9, 'DLMO serves as the primary objective gold-standard clinical marker for assessing circadian phase advance or delay.', 'Clinical Study', 'PubMed', '7434030', '10.1126/science.7434030'),
(2, 2, 'CSF Orexin-A concentration <= 110 pg/mL (or < 1/3 of mean control values) is the definitive diagnostic criterion for Narcolepsy Type 1.', 'Clinical Diagnostic Study', 'PubMed', '10615891', '10.1016/S0140-6736(99)05582-8'),
(3, 3, 'Elevated evening and midnight nadir cortisol levels reflect systemic hypothalamic-pituitary-adrenal hyperarousal in chronic primary insomnia.', 'Review / Clinical Study', 'PubMed', '19481481', '10.1016/j.smrv.2009.04.002'),
(4, 4, 'AHI >= 15 events/hr (or >= 5 with symptoms) establishes the primary objective polysomnographic diagnosis and severity staging of OSA.', 'Clinical Diagnostic Study', 'PubMed', '23541571', '10.5664/jcsm.3070'),
(4, 5, 'Circulating interleukin-6 (IL-6) levels are significantly elevated in Obstructive Sleep Apnea, correlating with nocturnal hypoxemia.', 'Clinical Study', 'PubMed', '9141509', '10.1210/jcem.82.5.9141509'),
(4, 6, 'Circulating tumor necrosis factor-alpha (TNF-alpha) is significantly elevated in patients with Obstructive Sleep Apnea in meta-analyses.', 'Meta-Analysis', 'PubMed', '23541571', '10.5664/jcsm.3070'),
(5, 8, 'Low serum ferritin (< 50-75 ng/mL) reflects central iron insufficiency and inversely correlates with Restless Legs Syndrome symptom severity.', 'Clinical Study', 'PubMed', '8042674', '10.1093/ageing/23.3.200');
